import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("LIF-11 vendor lifecycle", () => {
  test("sign-in ignores the case of the email address", { tag: "@LIF-11" }, async ({ request, apiAs }) => {
    // Act
    const response = await request.post("/api/auth/login", {
      data: { email: "Member@Northwind.TEST", password: PASSWORD },
    });

    // Assert
    const body = await expectStatus<{ access_token: string; user: { email: string } }>(response, 200);
    expect(body.user.email).toBe("member@northwind.test");

    // The current user's email, as reported by /api/me, matches the lowercase form.
    const member = await apiAs("member");
    const me = await expectStatus<{ email: string }>(await member.get("/api/me"), 200);
    expect(me.email).toBe("member@northwind.test");
  });
});
